#include "utils/json_write.h"
#include <stdio.h>

// 内部辅助函数，用于将 INTERP_TYPE 枚举转换为字符串
static const char* interp_type_to_string(INTERP_TYPE type) {
    switch (type) {
        case RAPID: return "RAPID";
        case LINE: return "LINE";
        case CIRCLE_CW: return "CIRCLE_CW";
        case CIRCLE_CCW: return "CIRCLE_CCW";
        case SPLINE: return "SPLINE";
        case RIGID_TAP: return "RIGID_TAP";
        case PROBE: return "PROBE";
        default: return "UNKNOWN";
    }
}

/**
 * @brief 将TC_QUEUE的内容写入JSON文件。
 * @param filepath 要写入的文件的路径。
 * @param pl_queue 指向TC_QUEUE的指针。
 * @return GNC_RES 操作结果。成功返回 GNC_OPERATOR_SUCCESS。
 * @version v1.0
 * @author 许晓婷
 * @date 2025/10/20
 */
GNC_RES write_plan_queue_file(const char *filepath, PLAN_QUEUE* pl_queue) {
    if (filepath == NULL || pl_queue == NULL) {
        return GNC_PARAM_UNVALID;
    }

    FILE *file = fopen(filepath, "w");
    if (file == NULL) {
        perror("Error opening file for writing pl_queue");
        return GNC_OPERATOR_ERROR;
    }

    fprintf(file, "[\n");

    int size = queue_get_size(pl_queue);
    for (int i = 0; i < size; ++i) {
        PLAN_BLOCK* pl_block = queue_get_block(pl_queue, i);
        if (pl_block == NULL) {
            continue; // 如果获取为空则跳过
        }

        fprintf(file, "  {\n");
        fprintf(file, "    \"type\": \"%s\",\n", interp_type_to_string(pl_block->type));
        fprintf(file, "    \"length\": %f,\n", pl_block->length);
        fprintf(file, "    \"angle_rad\": %f,\n", pl_block->angle_rad);
        fprintf(file, "    \"start_vel\": %f,\n", pl_block->start_vel);
        fprintf(file, "    \"end_vel\": %f,\n", pl_block->end_vel);
        fprintf(file, "    \"max_vel\": %f,\n", pl_block->max_vel);
        fprintf(file, "    \"start_pos\": {\"x\": %f, \"y\": %f, \"z\": %f},\n", pl_block->start_pos.x, pl_block->start_pos.y, pl_block->start_pos.z);
        fprintf(file, "    \"end_pos\": {\"x\": %f, \"y\": %f, \"z\": %f}\n", pl_block->end_pos.x, pl_block->end_pos.y, pl_block->end_pos.z);
        
        fprintf(file, "  }");
        if (i < size - 1) {
            fprintf(file, ",\n");
        } else {
            fprintf(file, "\n");
        }
    }

    fprintf(file, "]\n");

    fclose(file);

    return GNC_OPERATOR_SUCCESS;
}

/**
 * @brief 将VEL_PROFILE的内容写入JSON文件。
 * @param filepath 要写入的文件的路径。
 * @param profile 指向VEL_PROFILE的指针。
 * @return GNC_RES 操作结果。
 * @version v1.0
 * @author 许晓婷
 * @date 2025/10/20
 */
GNC_RES write_vel_profile_file(const char *filepath, VEL_PROFILE* profile) {
    if (filepath == NULL || profile == NULL) {
        return GNC_PARAM_UNVALID;
    }
    
    FILE *file = fopen(filepath, "w");
    if (file == NULL) {
        perror("Error opening file for writing vel_profile");
        return GNC_OPERATOR_ERROR;
    }

    fprintf(file, "{\n");
    fprintf(file, "  \"t\": [%f, %f, %f, %f, %f, %f, %f],\n",
            profile->t[0], profile->t[1], profile->t[2], profile->t[3],
            profile->t[4], profile->t[5], profile->t[6]);
    fprintf(file, "  \"v\": [%f, %f, %f, %f, %f, %f, %f],\n",
            profile->v[0], profile->v[1], profile->v[2], profile->v[3],
            profile->v[4], profile->v[5], profile->v[6]);
    fprintf(file, "  \"s\": [%f, %f, %f, %f, %f, %f, %f],\n",
            profile->s[0], profile->s[1], profile->s[2], profile->s[3],
            profile->s[4], profile->s[5], profile->s[6]);
    fprintf(file, "  \"vs\": %f,\n", profile->vs);
    fprintf(file, "  \"ve\": %f,\n", profile->ve);
    fprintf(file, "  \"vpeak\": %f,\n", profile->vpeak);
    fprintf(file, "  \"ata\": %f,\n", profile->ata);
    fprintf(file, "  \"atd\": %f,\n", profile->atd);
    fprintf(file, "  \"jta\": %f,\n", profile->jta);
    fprintf(file, "  \"jtd\": %f,\n", profile->jtd);
    fprintf(file, "  \"t_cycle\": %f,\n", profile->t_cycle);
    fprintf(file, "  \"s1_\": %f,\n", profile->s1_);
    fprintf(file, "  \"s5_\": %f\n", profile->s5_);
    fprintf(file, "}\n");

    fclose(file);

    return GNC_OPERATOR_SUCCESS;
}

/**
 * @brief 将插补值s写入JSON文件。
 * @param filepath 要写入的文件的路径。
 * @param s double类型的插补值。
 * @return GNC_RES 操作结果。
 * @version v1.0
 * @author 许晓婷
 * @date 2025/10/20
 */
GNC_RES write_interp_s_file(const char *filepath, double s) {
    if (filepath == NULL) {
        return GNC_PARAM_UNVALID;
    }

    FILE *file = fopen(filepath, "w");
    if (file == NULL) {
        perror("Error opening file for writing interp_s");
        return GNC_OPERATOR_ERROR;
    }

    fprintf(file, "{\n");
    fprintf(file, "  \"s\": %f\n", s);
    fprintf(file, "}\n");

    fclose(file);

    return GNC_OPERATOR_SUCCESS;
}

static const char* interp_mode_to_string(NC_MODE mode) {
    switch (mode) {
        case MODE_ALARM: return "MODE_ALARM";
        case MODE_IDLE: return "MODE_IDLE";
        case MODE_HOMING: return "MODE_HOMING";
        case MODE_MEM: return "MODE_MEM";
        case MODE_JOG: return "MODE_JOG";
        case MODE_MPG: return "MODE_MPG";
        case MODE_MDI: return "MODE_MDI";
        default: return "UNKNOWN";
    }
}

static const char* interp_event_to_string(SYS_EVENT event) {
    switch (event) {
        case SYS_EVENT_NONE: return "NONE";
        case SYS_EVENT_PAUSE: return "PAUSE";
        case SYS_EVENT_RERUN: return "RERUN";
        case SYS_EVENT_RESET: return "RESET";
        case SYS_EVENT_X: return "X";
        case SYS_EVENT_Y: return "Y";
        case SYS_EVENT_Z: return "Z";
        default: return "UNKNOWN";
    }
}

static const char* interp_state_to_string() {
    switch (sys->current_mode) {
        case MODE_HOMING: 
            switch(x_homing_tp->homing_state){
                case ABS_EXEC_IDLE: return "IDLE";
                case ABS_EXEC_HOMING: return "HOMING";
                case ABS_EXEC_CANCELING: return "CANCELING";
            }
        case MODE_MEM: 
            switch(mem_exec_state){
                case EXEC_IDLE: return "IDLE";
                case EXEC_RUNNING: return "RUNING";
                case EXEC_PAUSING: return "PAUSING";
                default: return "UNKNOWN";
            }
        default: return "UNKNOWN";
    }
}


GNC_RES write_all_data_file(const char *filepath){
    if (filepath == NULL) {
        return GNC_PARAM_UNVALID;
    }

    FILE *file = fopen(filepath, "w");
    if (file == NULL) {
        perror("Error opening file for writing interp_s");
        return GNC_OPERATOR_ERROR;
    }

    fprintf(file, "{\n");
    fprintf(file, "  \"加工模式\": \"%s\",\n", interp_mode_to_string(sys->current_mode));
    fprintf(file, "  \"系统状态\": \"%s\",\n", interp_state_to_string());
    fprintf(file, "  \"系统事件\": \"%s\",\n", interp_event_to_string(sys->nc_event));
    fprintf(file, "  \"当前位置\": [%f, %f, %f],\n", hal->current_pos.x, hal->current_pos.y, hal->current_pos.z);
    fprintf(file, "  \"零点位置\": [%f, %f, %f],\n", params->home_pos.x, params->home_pos.y, params->home_pos.z);
    fprintf(file, "  \"自动加工：插补距离\":%f,\n", hal->interp_pin);
    fprintf(file, "  \"自动加工：剩余距离\":%f,\n", cycle_tp->remain_distance);
    fprintf(file, "  \"当前速度\": [%f, %f, %f, %f]\n", hal->current_vel, hal->x_current_vel, hal->y_current_vel, hal->z_current_vel);
    fprintf(file, "}\n");

    fclose(file);

    return GNC_OPERATOR_SUCCESS;
}